+/** Closes a suite's sockets before its engines, waiting until the servers observed every close. */
+export async function stopEnginesAfterClientsClose(
+  suiteClients: WebSocket[],
+  suiteServers: Array<Pick<HalServer, 'wss' | 'stop'>>
+): Promise<void> {
+  for (const client of suiteClients.splice(0)) client.terminate();
+  for (const hal of suiteServers.splice(0)) {
+    for (let attempt = 0; attempt < 50 && hal.wss.clients.size !== 0; attempt++) {
